export function isDxfStyle(styleId) {
    return Boolean(DXF_GARMENT_STYLES[styleId]);
}

export function mirrorVerticesX(vertices, width) {
    const w = width ?? Math.max(...vertices.map(p => p.x));
    return [...vertices].reverse().map(p => ({
        x: Math.round((w - p.x) * 10) / 10,
        y: p.y
    }));
}

/**
 * 构建指定 DXF 款式的裁片列表。
 * - fabricFilter:默认 '面布'（同种面料同床排料符合真实裁剪工艺；传 'ALL' 则合并该文件内全部面料裁片）
 * - splitMirrorPairs:若为 true，对 Quantity=1,1 (L:1-R:1) 的裁片拆分为左片与镜像右片，实现真实左右对称互补密排；
 *   若为 false，则保持单一条目 quantity=2（用于经典 marker-demo 行数契约兼容）。
 */
export function buildDxfStyleParts(styleId, {
    sizeCounts = {M: 1, L: 1},
    fabricFilter = '面布',
    splitMirrorPairs = false
} = {}) {
    const style = DXF_GARMENT_STYLES[styleId];
    if (!style) throw new Error('未知 DXF 纸样款式：' + styleId);
    const sizeMap = {
        M: style.defaultPair.M,
        L: style.defaultPair.L,
        '110': '110', '120': '120', '130': '130', '140': '140', '150': '150', '160': '160'
    };
    const selectedPieces = style.pieces.filter(p => fabricFilter === 'ALL' || p.fabric === fabricFilter);
    const parts = [];
    for (const [sizeKey, count] of Object.entries(sizeCounts)) {
        if (!count || count <= 0) continue;
        const dxfSize = sizeMap[sizeKey] || '130';
        const sizeLabel = (sizeKey === 'M' || sizeKey === 'L') ? `${sizeKey}码(${dxfSize})` : `${dxfSize}码`;
        for (const piece of selectedPieces) {
            const geom = piece.sizes[dxfSize] || piece.sizes['130'];
            if (!geom) continue;
            const baseVertices = geom.v.map(([x, y]) => ({x, y}));
            const baseShape = polygon(baseVertices);
            if (splitMirrorPairs && piece.pairMirror && piece.quantity === 2) {
                const rightShape = polygon(mirrorVerticesX(baseVertices, geom.w));
                parts.push({
                    name: `${sizeLabel} · ${piece.name}(左)`,
                    quantity: count,
                    shape: baseShape,
                    allowRotation: false,
                    fabric: piece.fabric,
                    dxfSize
                });
                parts.push({
                    name: `${sizeLabel} · ${piece.name}(右)`,
                    quantity: count,
                    shape: rightShape,
                    allowRotation: false,
                    fabric: piece.fabric,
                    dxfSize
                });
            } else {
                parts.push({
                    name: `${sizeLabel} · ${piece.name}`,
                    quantity: piece.quantity * count,
                    shape: baseShape,
                    allowRotation: false,
                    fabric: piece.fabric,
                    dxfSize
                });
            }
        }
    }
    return parts.map((part, idx) => ({...part, id: idx + 1}));
}

/**
 * 客户端解析 AAMA/ASTM 服装或通用 CAD DXF 文本/二进制流，委托给通用 dxf-parser.js 引擎并保持向后兼容。
 */
export function parseDxfGarmentText(text, fileName = 'pattern.dxf', options = {}) {
    return parseDxfText(text, { ...options, fileName });
}
